{
  "name": "invalid-credentials",
  "priority": 50,
  "request": {
    "method": "POST",
    "urlPathPattern": "/auth/realms/[^/]+/protocol/openid-connect/token"
  },
  "response": {
    "status": 401,
    "headers": {
      "Content-Type": "application/json",
      "X-Mock-Only": "true"
    },
    "body": "{\"error\": \"invalid_client\", \"error_description\": \"Use mock tenant and dummy client credentials\"}"
  }
}

data.unauthorized-or-unimplemented.json:
{
  "name": "unauthorized-or-unimplemented",
  "priority": 99,
  "request": {
    "method": "ANY",
